/* Dynamic diagnostic experience. Recognition evidence remains independent of rewards. */
state.cvcReports??=[];
state.voiceSpeed??=1.12;
let cueStartedAt=0,cueDone=false,cvcRun=null,cvcBuild=[],cvcLocked=false;
browserToken=function(text,token){return new Promise(resolve=>{
 if(!window.speechSynthesis||token!==gameCueToken){resolve(false);return;}
 const u=new SpeechSynthesisUtterance(text),voice=browserVoice();if(voice)u.voice=voice;u.lang='en-US';u.rate=state.voiceSpeed;u.pitch=1.05;
 let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);gameWaiters.delete(finish);resolve(ok&&token===gameCueToken);};
 const timer=setTimeout(()=>finish(false),6000);gameWaiters.add(finish);u.onend=()=>finish(true);u.onerror=()=>finish(false);try{speechSynthesis.speak(u);}catch{finish(false);}
 });};
// Recorded phonemes retain their original speed and pitch. Only silence between cues is shorter.
autoGameCue=async function(){
 cancelGameCue();unlockGameAudio();const q=quiz?.items[quiz.index];if(!q||view!=='assessment')return;
 const run=quiz,token=gameCueToken;cueStartedAt=Date.now();cueDone=false;heardQuestion=GameCore.key(q);
 const status=document.getElementById('cueStatus');if(status){status.textContent='';status.setAttribute('aria-busy','true');}
 document.getElementById('autoAudioNotice')?.setAttribute('hidden','');
 quiz.replays??={};quiz.replays[heardQuestion]=(quiz.replays[heardQuestion]||0)+1;
 let ok=true;const plan=DiagnosisCore.cuePlan(q);
 for(let i=0;i<plan.length;i++){
  if(token!==gameCueToken||quiz!==run)return;const cue=plan[i];
  if(q.task==='audio')document.querySelectorAll('.audio-option').forEach(e=>e.classList.toggle('is-listening',Number(e.dataset.option)===i));
  document.querySelectorAll('.cue-beats i').forEach((e,n)=>e.classList.toggle('active',n===i));
  const played=cue.kind==='phoneme'?await gameClip('assets/phonemes/'+cue.value+'.mp3',token):await voiceToken(cue.kind,cue.value,token);ok=played&&ok;
  if(played&&q.task==='audio')markOptionHeard(q,i);
  if(i<plan.length-1&&!await gamePause(q.task==='name'?95:100,token))return;
 }
 if(token!==gameCueToken||quiz!==run)return;cueDone=true;quiz.cueEndedAt=Date.now();persist();
 document.querySelectorAll('.is-listening,.cue-beats .active').forEach(e=>e.classList.remove('is-listening','active'));if(status)status.setAttribute('aria-busy','false');if(!ok)audioBlocked();
};
listenSoundOption=async function(i){const q=quiz?.items[quiz.index];if(!q||q.task!=='audio'||!q.options[i])return;cancelGameCue();const token=gameCueToken,run=quiz;const el=document.querySelector(`.audio-option[data-option="${i}"]`);el?.classList.add('is-listening');const ok=await gameClip('assets/phonemes/'+q.options[i]+'.mp3',token);if(token!==gameCueToken||run!==quiz)return;el?.classList.remove('is-listening');if(ok)markOptionHeard(q,i);else audioBlocked();};
function burstAt(button){const host=button.closest('.game-task,.cvc-stage')||button;host.classList.add('answer-burst');const spark=document.createElement('span');spark.className='tap-spark';spark.textContent='✦';button.append(spark);setTimeout(()=>{spark.remove();host.classList.remove('answer-burst');},600);}
function phonicsSpelling(q){if(q.mode!=='sound')return;document.querySelectorAll('.toy-answer[data-letter="q"]').forEach(el=>{const letter=el.querySelector('.toy-letter');if(letter)letter.innerHTML='Qu<span class="toy-eyes"><i></i><i></i></span>';const lower=el.querySelector('.toy-lower');if(lower)lower.textContent='qu';el.setAttribute('aria-label','Буквосочетание qu');});}
const renderBaseDiagnostic=renderDiagnostic;
renderDiagnostic=function(){
 const q=quiz?.items[quiz.index];if(!q){finishDiagnostic();return;}const task=q.task;if(task==='ending')q.task='letter';renderBaseDiagnostic();q.task=task;
 if(view!=='assessment')return;quiz.questionOpenedAt=Date.now();cueStartedAt=0;cueDone=false;
 const headings={name:'Поймай букву!',letter:'Кто так звучит?',picture:'Найди картинку!',word:'Поймай первый звук!',ending:'Поймай последний звук!',audio:'Найди её звук!'};
 const heading=document.querySelector('.game-heading');if(heading)heading.innerHTML=`<span class="mission-chip">${q.mode==='name'?'✦ Имена букв':'♫ Звуковая миссия'}</span><h1>${headings[task]}</h1>${task==='ending'?'<span class="task-visual-hint" aria-label="Последний звук">● — ● — <b>●</b></span>':''}`;
 phonicsSpelling(q);
 const bar=document.querySelector('.game-audio-bar');if(bar)bar.insertAdjacentHTML('beforeend','<span class="cue-beats" aria-hidden="true"><i></i><i></i><i></i></span>');
 document.querySelector('.adventure-progress').innerHTML=diagnosticProgress();
 if(!document.querySelector('.sound-adventure>#rewards'))document.querySelector('.sound-adventure').insertAdjacentHTML('beforeend',rewardCollection());
};
diagnosticProgress=function(){const p=GameCore.progress(quiz),c=DiagnosisCore.coverage(quiz);return `<section class="alphabet-dashboard" id="alphabetDashboard"><div class="flight-progress"><span class="flight-rocket">🚀</span><div><strong>${p.answered} <small>/ 52</small></strong><span>До финиша ${p.remainingQuestions}</span></div><div class="skill-counts"><span>Названия <b>${c.names}/26</b></span><span>Звуки <b>${c.sounds}/26</b></span></div></div><div class="alphabet-meter" role="progressbar" aria-label="Прогресс диагностики" aria-valuemin="0" aria-valuemax="52" aria-valuenow="${p.answered}"><div style="width:${p.percent}%"></div></div><div class="alphabet-map">${p.letters.map(d=>{const problem=(d.name.completed&&d.name.errors.length)||(d.sound.completed&&d.sound.errors.length);return `<span class="alphabet-stop ${problem?'has-problem':d.complete?'is-clean':''}" aria-label="${d.letter.toUpperCase()}: ${problem?'были ошибки':d.complete?'готово':'впереди'}"><b>${d.letter.toUpperCase()}</b><span class="letter-skill-dots"><i class="${d.name.completed?(d.name.errors.length?'dot-problem':'dot-clean'):''}"></i><i class="${d.sound.completed?(d.sound.errors.length?'dot-problem':'dot-clean'):''}"></i></span></span>`;}).join('')}</div><div class="streak-ladder"><b>✦ ${p.streak} букв подряд</b>${rewardTiers.map(t=>`<span class="${p.streak>=t.n?'tier-complete':''}">${t.symbol} ${t.n}</span>`).join('')}</div><p class="progress-help">Две точки: название и звук. Золотые — были ошибки. Медаль за название + звук без ошибок.</p></section>`;};
answerDiagnostic=function(answer,button){
 if(gameLocked||view!=='assessment'||!button)return;const q=quiz?.items[quiz.index];if(!q)return;
 const outcome=GameCore.answer(quiz,answer,true);if(!outcome.accepted)return;
 outcome.event.responseMs=Math.max(0,Date.now()-quiz.questionOpenedAt);outcome.event.cueInterrupted=!cueDone;outcome.event.cueStarted=cueStartedAt>0;outcome.event.listenedOptions=(quiz.listenedOptions?.[GameCore.key(q)]||[]).slice();
 cancelGameCue();state.pendingQuiz=quiz;persist();playFeedback(outcome.correct);refreshDiagnosticProgress();
 if(!outcome.correct){button.disabled=true;const card=button.closest('.audio-option,.picture-option')||button;card.classList.add(card.classList.contains('toy-answer')?'dimmed':'choice-is-wrong');card.classList.add('wrong-wobble');setTimeout(()=>card.classList.remove('wrong-wobble'),450);return;}
 gameLocked=true;document.querySelectorAll('.toy-answer,.audio-select,.picture-select').forEach(b=>b.disabled=true);button.classList.add('celebrate');burstAt(button);
 const fresh=collectMilestones(),run=quiz;const next=()=>{if(view!=='assessment'||quiz!==run)return;quiz.index++;persist();if(quiz.index<quiz.items.length)renderDiagnostic();else finishDiagnostic();};
 diagnosticTimer=setTimeout(()=>{if(view!=='assessment'||quiz!==run)return;if(fresh.length)showReward(fresh[0],next);else next();},480);
};
const parentHomeBase=renderParentHome;
renderParentHome=function(){parentHomeBase();document.querySelectorAll('.scope-tags span').forEach(e=>{if(e.textContent==='4 формата заданий')e.textContent='5 звуковых форматов';});document.querySelector('.parent-heading p').textContent='От букв и звуков — к коротким CVC-словам. Отдельные результаты по каждому навыку.';const scope=document.querySelector('.diagnosis-start+.scope-note');if(scope)scope.textContent='После уверенного результата по буквам и звукам автоматически открывается диагностика CVC. Любую часть можно пройти отдельно. Устное произношение автоматически пока не оценивается.';app.insertAdjacentHTML('beforeend',`<section class="cvc-parent-card"><div class="cvc-island-icon">abc<span>✦</span></div><div><span class="eyebrow">СЛЕДУЮЩИЙ ЭТАП</span><h2>CVC-слова</h2><p>12 заданий · чтение → картинка · сборка слова · похожие слова</p><button class="primary" onclick="openCvcIntro()">${state.pendingCvc?'Продолжить CVC':'Проверить CVC'} ↗</button></div></section>${rewardCollection()}`);};
showDiagnosticIntro=function(){showModal('<div class="diagnosis-intro"><h2>Два острова открытий ✦</h2><p><b>1. Буквы и звуки:</b> 52 коротких задания. Названия A–Z идут по порядку, звуковые игры — небольшими блоками.</p><p><b>2. CVC-слова:</b> 12 заданий. Если буквы получаются уверенно, перейдём к словам автоматически.</p><p>Можно отвечать сразу. Ошибочный вариант погаснет, а первая попытка останется в отчёте.</p><button class="primary" onclick="modal.close();startDiagnostic()">Поехали! 🚀</button></div>');};
finishDiagnostic=function(){clearTimeout(diagnosticTimer);cancelGameCue();const d=DiagnosisCore.report(quiz,state.name);if(!d.completed){renderDiagnostic();return;}d.assessmentVersion=quiz.assessmentVersion;d.phonicsConvention='Базовые звуки: C/K=/k/, G=/g/, Y=/j/, X=/ks/, Q проверяется как qu=/kw/. Альтернативные звуки букв не проверялись.';state.diagnostic=d;state.diagnosticReports.push(d);state.sessions.push({type:'diagnostic',at:d.at,names:d.names,sounds:d.sounds,details:d.detail});delete state.pendingQuiz;persist();if(d.passed)startCvcDiagnostic();else navigate('results');};
function openCvcIntro(){if(state.pendingCvc){cvcRun=state.pendingCvc;resumeCvc();return;}showModal('<div class="diagnosis-intro"><h2>Остров коротких слов</h2><p>12 заданий: прочитай и выбери картинку, собери услышанное слово и найди слово среди похожих.</p><p>Каждый формат сохраняется отдельно. Проверка не оценивает устное произношение.</p><button class="primary" onclick="modal.close();startCvcDiagnostic()">К словам! 🚀</button></div>');}
function startCvcDiagnostic(){cancelGameCue();unlockGameAudio();cvcRun=CvcCore.create();state.pendingCvc=cvcRun;persist();renderCvc();}
function resumeCvc(){while(cvcRun.index<cvcRun.items.length&&CvcCore.events(cvcRun,cvcRun.items[cvcRun.index]).some(e=>e.correct))cvcRun.index++;if(cvcRun.index>=cvcRun.items.length)finishCvc();else renderCvc();}
function cvcArt(word){return pictureArt(CvcCore.art[word]);}
function renderCvc(){
 cancelGameCue();clearTimeout(diagnosticTimer);if(!cvcRun?.items[cvcRun.index]){finishCvc();return;}view='cvc-assessment';document.body.classList.add('diagnostic-child');cvcBuild=[];cvcLocked=false;
 const q=cvcRun.items[cvcRun.index],wrong=CvcCore.events(cvcRun,q).filter(e=>!e.correct).map(e=>e.answer);cvcRun.questionOpenedAt=Date.now();
 let body='';if(q.task==='read-picture')body=`<div class="cvc-word" aria-label="Слово ${q.word}">${[...q.word].map((l,i)=>`<span style="--tile:${i}">${l}</span>`).join('')}</div><div class="picture-options">${q.options.map(w=>`<div class="picture-option ${wrong.includes(w)?'choice-is-wrong':''}"><button class="picture-select" aria-label="Картинка ${w}" onclick="submitCvc('${w}',this)" ${wrong.includes(w)?'disabled':''}>${cvcArt(w)}<span>✦</span></button></div>`).join('')}</div>`;
 if(q.task==='listen-word')body=`<div class="cvc-sound-orb" aria-hidden="true">♫</div><div class="cvc-word-options">${q.options.map(w=>`<button class="cvc-word-choice ${wrong.includes(w)?'dimmed':''}" onclick="submitCvc('${w}',this)" ${wrong.includes(w)?'disabled':''}>${w}</button>`).join('')}</div>`;
 if(q.task==='build')body=`<div class="build-slots" aria-label="Собранное слово"><button onclick="undoCvc()" aria-label="Убрать последнюю букву">·</button><button onclick="undoCvc()" aria-label="Убрать последнюю букву">·</button><button onclick="undoCvc()" aria-label="Убрать последнюю букву">·</button></div><div class="cvc-tiles">${q.options.map((l,i)=>`<button class="cvc-tile toy-${i%3}" onclick="addCvcTile('${l}',this)">${l}</button>`).join('')}</div><button class="text-btn build-undo" onclick="undoCvc()">↶</button>`;
 const titles={'read-picture':'Прочитай. Найди картинку!','listen-word':'Поймай слово!','build':'Собери слово!'};
 app.innerHTML=`<div class="sound-adventure cvc-adventure"><div class="adventure-toolbar"><button class="secondary" onclick="pauseCvc()">Ⅱ Пауза</button><span>CVC · ${cvcRun.index+1} / 12</span></div><section class="adventure-stage cvc-stage"><div class="scene-cloud cloud-a"></div><div class="scene-cloud cloud-b"></div><div class="scene-hill hill-a"></div><div class="scene-hill hill-b"></div><div class="game-buddy"><div class="buddy-window"><img src="assets/orbit-world.png" alt="Орби"></div></div><div class="adventure-play"><div class="game-heading"><span class="mission-chip">🏝 Остров коротких слов</span><h1>${titles[q.task]}</h1></div><div class="game-audio-bar">${q.task==='read-picture'?'<span class="read-visual">👀 → 🖼</span>':'<button class="game-replay" onclick="cueCvc()" aria-label="Послушать слово">♫</button><span id="cueStatus" role="status"></span>'}</div><div class="game-task" data-task="${q.task}">${body}</div><div id="autoAudioNotice" hidden></div></div></section><div class="cvc-journey" role="progressbar" aria-label="Прогресс CVC" aria-valuenow="${cvcRun.index}" aria-valuemin="0" aria-valuemax="12">${cvcRun.items.map((item,i)=>`<span class="${i<cvcRun.index?'done':i===cvcRun.index?'now':''}">${i<cvcRun.index?'✦':i+1}</span>`).join('')}</div>${rewardCollection()}</div>`;
 state.pendingCvc=cvcRun;persist();window.scrollTo(0,0);if(q.task!=='read-picture')gameTimers.push(setTimeout(cueCvc,100));
}
async function cueCvc(){cancelGameCue();unlockGameAudio();const q=cvcRun?.items[cvcRun.index];if(!q||view!=='cvc-assessment'||q.task==='read-picture')return;const token=gameCueToken;document.querySelector('.cvc-sound-orb')?.classList.add('playing');const ok=await voiceToken('word',q.word,token);if(token!==gameCueToken)return;document.querySelector('.cvc-sound-orb')?.classList.remove('playing');if(!ok){const e=document.getElementById('autoAudioNotice');if(e){e.hidden=false;e.innerHTML='<button class="primary" onclick="cueCvc()">Включить звук</button>';}}}
function addCvcTile(letter,button){if(cvcLocked||cvcBuild.length>=3)return;cvcBuild.push(letter);drawCvcSlots();button.classList.remove('tile-pop');void button.offsetWidth;button.classList.add('tile-pop');if(cvcBuild.length===3)submitCvc(cvcBuild.join(''),document.querySelector('.build-slots'));}
function drawCvcSlots(){document.querySelectorAll('.build-slots button').forEach((el,i)=>{el.textContent=cvcBuild[i]||'·';el.classList.toggle('filled',!!cvcBuild[i]);});}
function undoCvc(){if(cvcLocked)return;cvcBuild.pop();drawCvcSlots();}
function submitCvc(selected,button){
 if(cvcLocked||view!=='cvc-assessment')return;const q=cvcRun.items[cvcRun.index],out=CvcCore.answer(cvcRun,selected);if(!out.accepted){if(q.task==='build'){cvcBuild=[];drawCvcSlots();}return;}
 out.event.responseMs=Date.now()-cvcRun.questionOpenedAt;cancelGameCue();playFeedback(out.correct);state.pendingCvc=cvcRun;persist();
 if(!out.correct){const card=button.closest('.picture-option')||button;card.classList.add('wrong-wobble');if(q.task!=='build'){button.disabled=true;card.classList.add('dimmed');}else{cvcLocked=true;setTimeout(()=>{card.classList.remove('wrong-wobble');cvcBuild=[];drawCvcSlots();cvcLocked=false;},400);}return;}
 cvcLocked=true;button.classList.add('celebrate');burstAt(button);document.querySelectorAll('.cvc-word-choice,.picture-select,.cvc-tile').forEach(b=>b.disabled=true);
 const run=cvcRun;diagnosticTimer=setTimeout(()=>{if(view!=='cvc-assessment'||cvcRun!==run)return;cvcRun.index++;persist();if(cvcRun.index>=cvcRun.items.length)finishCvc();else renderCvc();},500);
}
function pauseCvc(){clearTimeout(diagnosticTimer);cancelGameCue();state.pendingCvc=cvcRun;persist();showModal('<h2>Сделаем паузу?</h2><p>Ответы сохранены.</p><div class="controls"><button class="primary" onclick="modal.close();navigate(\'home\')">В кабинет</button><button class="secondary" onclick="modal.close();resumeCvc()">Продолжить</button></div>');}
function finishCvc(){clearTimeout(diagnosticTimer);cancelGameCue();const d=CvcCore.report(cvcRun,state.name);if(!d.completed){renderCvc();return;}state.cvcReports.push(d);state.lastCvc=d;delete state.pendingCvc;state.sessions.push({type:'cvc-diagnostic',at:d.at,score:d.score,total:12});persist();navigate('results');playFeedback(true);}
function cvcReportCard(d){const labels={'read-picture':'Чтение → картинка',build:'Сборка услышанного слова','listen-word':'Узнавание слова на слух'};return `<section class="parent-report cvc-report"><span class="eyebrow">ОТДЕЛЬНАЯ ДИАГНОСТИКА</span><h2>CVC-слова · ${escapeHTML(d.childName)}</h2><div class="cvc-score-breakdown">${Object.entries(labels).map(([task,label])=>{const rows=d.detail.filter(r=>r.task===task);return `<div><span>${label}</span><strong>${rows.filter(r=>r.firstTry).length}<small>/${rows.length}</small></strong></div>`;}).join('')}</div><p class="scope-note">${d.scope} Первая попытка сохраняется, даже если затем слово исправлено.</p><div class="report-table-scroll"><table class="diagnostic-table"><thead><tr><th>Слово</th><th>Формат</th><th>Первая попытка</th><th>Ошибочные ответы</th></tr></thead><tbody>${d.detail.map(r=>`<tr><th>${r.word}</th><td>${labels[r.task]}</td><td>${r.firstTry?'Верно':'Были ошибки'}</td><td>${r.errors.map(e=>e.answer).join(' → ')||'—'}</td></tr>`).join('')}</tbody></table></div><div class="controls"><button class="primary" onclick="startCvcDiagnostic()">Проверить CVC ещё раз</button><button class="secondary" onclick="exportCvcReport()">Скачать CVC-отчёт</button></div></section>`;}
function exportCvcReport(){const d=state.lastCvc;if(!d)return;const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cvc-diagnostic.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const reportsBase=renderParentReports;
renderParentReports=function(){reportsBase();if(!state.diagnostic?.detail&&state.lastCvc)app.innerHTML='<div class="parent-heading"><h1>Результаты диагностики</h1></div>';if(state.diagnostic?.detail){const notes=document.querySelector('.report-findings+.scope-note');if(notes)notes.textContent='Здесь — результат по буквам. CVC проверяется отдельно ниже. Исправленный ответ не меняет результат первой попытки. Устное произношение и связный текст автоматически не оценивались.';const findings=document.querySelector('.report-actions');if(findings)findings.insertAdjacentHTML('beforeend','<button class="primary" onclick="openCvcIntro()">К CVC-словам ↗</button>');}if(state.lastCvc)app.insertAdjacentHTML('beforeend',cvcReportCard(state.lastCvc));app.insertAdjacentHTML('beforeend',rewardCollection());};
const settingsBase=renderParentSettings;
renderParentSettings=function(){settingsBase();const section=document.querySelector('.settings-card:last-child');section?.insertAdjacentHTML('beforeend',`<label class="field tempo-field">Темп названий и слов<select onchange="state.voiceSpeed=Number(this.value);persist()"><option value="1" ${state.voiceSpeed===1?'selected':''}>Спокойный</option><option value="1.12" ${state.voiceSpeed===1.12?'selected':''}>Динамичный</option><option value="1.25" ${state.voiceSpeed===1.25?'selected':''}>Быстрый</option></select></label><p class="settings-note">Названия — три коротких повтора. Звуки — один раз. Ответ доступен сразу, воспроизведение останавливается при выборе. Записи фонем сохраняют исходный темп.</p><details class="parent-details"><summary>Проверить названия и звуки A–Z</summary><p>Базовые звуки: C и K — /k/, G — /g/, Y — /j/, X — /ks/. У Q проверяется сочетание qu — /kw/. Дополнительные звуки букв пока не оцениваются.</p><div class="audio-audit">${alphabet.map(l=>`<div><b>${l.toUpperCase()}</b><button onclick="auditAudio('letter','${l}')">Название ♫</button><button onclick="auditAudio('phoneme','${l}')">${l==='q'?'Звук qu':'Звук'} ♫</button></div>`).join('')}</div></details>`);};
async function auditAudio(kind,letter){cancelGameCue();unlockGameAudio();if(kind==='phoneme')await gameClip('assets/phonemes/'+letter+'.mp3',gameCueToken);else await voiceToken('letter',letter,gameCueToken);}
const navBase=navigate;
navigate=function(next){clearTimeout(diagnosticTimer);cancelGameCue();if(next==='rewards'){document.body.classList.remove('diagnostic-child');view=next;app.innerHTML='<div class="parent-heading"><h1>Сокровища Орби</h1><p>Медали за 5, 10, 15, 20 и все 26 букв подряд: название и звук без ошибок с первой попытки.</p></div>'+rewardCollection();}else if(next==='cvc'){view=next;document.body.classList.remove('diagnostic-child');app.innerHTML='<div class="parent-heading"><h1>Диагностика CVC</h1><p>Отдельный этап проверки коротких слов.</p></div><button class="primary" onclick="openCvcIntro()">'+(state.pendingCvc?'Продолжить':'Начать')+' CVC ↗</button>'+(state.lastCvc?cvcReportCard(state.lastCvc):'');}else navBase(next);const routes=[['home','route','Диагностика'],['cvc','book','CVC-слова'],['results','chart','Отчёты'],['rewards','star','Награды'],['settings','world','Настройки']];document.getElementById('nav').innerHTML=routes.map(([id,ic,label])=>`<button class="${id===next?'active':''}" onclick="navigate('${id}')">${icon(ic)}${label}</button>`).join('');document.getElementById('crumb').textContent=routes.find(x=>x[0]===next)?.[2]||'Диагностика';window.scrollTo(0,0);};
navigate('home');
